package com.onewho.ai;
import android.app.*;import android.os.*;import android.Manifest;import android.content.*;import android.content.pm.PackageManager;import android.speech.*;import android.widget.*;import android.graphics.Color;import okhttp3.*;import org.json.*;import java.util.*;
public class MainActivity extends Activity implements RecognitionListener {
 EditText url,token,role,years,resume,manual; TextView status,question,answer,history; CheckBox consent,mock; Spinner length; SpeechRecognizer speech; WebSocket ws; boolean active=false,ready=false,busy=false; final Handler handler=new Handler(Looper.getMainLooper()); final OkHttpClient client=new OkHttpClient();
 LinearLayout root; String last=""; int generation=0;
 TextView text(String s){TextView t=new TextView(this);t.setText(s);t.setTextSize(17);t.setTextColor(Color.WHITE);root.addView(t);return t;}
 EditText field(String hint,String value){EditText e=new EditText(this);e.setHint(hint);e.setText(value);root.addView(e);return e;}
 void button(String label,Runnable r){Button b=new Button(this);b.setText(label);root.addView(b);b.setOnClickListener(v->r.run());}
 public void onCreate(Bundle b){super.onCreate(b);ScrollView scroll=new ScrollView(this);root=new LinearLayout(this);root.setOrientation(1);root.setPadding(32,48,32,48);root.setBackgroundColor(0xff101827);scroll.addView(root);setContentView(scroll);text("OneWho AI").setTextSize(30);text("Listen. Understand. Answer.");url=field("HTTPS backend URL","");token=field("Supabase access token","");token.setInputType(129);role=field("Job role","AWS DevOps Engineer");years=field("Experience (years)","4");resume=field("Verified resume text","");length=new Spinner(this);length.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"medium","short","detailed"}));root.addView(length);consent=new CheckBox(this);consent.setText("Everyone permits transcription and AI assistance");root.addView(consent);mock=new CheckBox(this);mock.setText("Mock interview mode");root.addView(mock);button("Upload resume",()->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("*/*");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,20);});button("Start listening",()->start());button("Pause / resume",()->{if(!ready)return;active=!active;if(active)listen();else{if(speech!=null)speech.cancel();status.setText("Paused");}});button("Stop",()->stop());status=text("Idle");question=text("");answer=text("");manual=field("Optional typed question","");button("Send question",()->send(manual.getText().toString()));history=text("");button("Clear history",()->{history.setText("");question.setText("");answer.setText("");});if(SpeechRecognizer.isRecognitionAvailable(this)){speech=SpeechRecognizer.createSpeechRecognizer(this);speech.setRecognitionListener(this);}}
 void start(){if(ready||ws!=null)return;if(!consent.isChecked()||token.length()==0||!url.getText().toString().startsWith("https://")){status.setText("Consent, HTTPS backend and access token required");return;}if(checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.RECORD_AUDIO},1);return;}try{JSONObject config=new JSONObject();config.put("token",token.getText());config.put("role",role.getText());config.put("experience",years.getText());config.put("resume",resume.getText());config.put("consent",true);config.put("mock",mock.isChecked());config.put("length",length.getSelectedItem());final boolean m=mock.isChecked();final int g=++generation;ws=client.newWebSocket(new Request.Builder().url(url.getText().toString().replaceAll("/+$","")+"/ws").build(),new WebSocketListener(){public void onOpen(WebSocket w,Response r){w.send(config.toString());runOnUiThread(()->{if(g!=generation)return;ready=true;active=true;last="";if(m)send("START");else listen();});}public void onMessage(WebSocket w,String msg){runOnUiThread(()->{if(g!=generation)return;try{JSONObject j=new JSONObject(msg);String s=j.optString("text");switch(j.getString("type")){case "question":question.setText(s);answer.setText("");break;case "delta":answer.append(s);break;case "done":busy=false;history.append("\n"+question.getText()+"\n"+answer.getText()+"\n");if(active)listen();break;case "error":stop();status.setText(s);}}catch(Exception e){status.setText("Invalid server response");}});}public void onFailure(WebSocket w,Throwable t,Response r){runOnUiThread(()->{if(g==generation){stop();status.setText("Connection failed");}});}public void onClosed(WebSocket w,int c,String r){runOnUiThread(()->{if(g==generation)stop();});}});status.setText("Connecting");}catch(Exception e){stop();status.setText("Invalid configuration");}}
 void send(String s){s=s.trim();if(!ready||busy||s.isEmpty()||s.equalsIgnoreCase(last))return;try{last=s;busy=true;if(speech!=null)speech.cancel();ws.send(new JSONObject().put("text",s).toString());status.setText("Generating answer");}catch(Exception e){busy=false;}}
 void listen(){if(!active||busy||speech==null)return;Intent i=new Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH);i.putExtra(RecognizerIntent.EXTRA_LANGUAGE_MODEL,RecognizerIntent.LANGUAGE_MODEL_FREE_FORM);i.putExtra(RecognizerIntent.EXTRA_LANGUAGE,"en-IN");try{speech.startListening(i);status.setText("Microphone listening");}catch(Exception e){status.setText("Voice unavailable; use typing");}}
 void stop(){generation++;active=false;ready=false;busy=false;if(speech!=null)speech.cancel();if(ws!=null){ws.close(1000,"Stopped");ws=null;}status.setText("Stopped");}
 public void onResults(Bundle b){if(!active)return;ArrayList<String> a=b.getStringArrayList(SpeechRecognizer.RESULTS_RECOGNITION);if(a!=null&&!a.isEmpty())send(a.get(0));if(!busy)handler.postDelayed(()->listen(),500);}
 public void onError(int e){if(active&&!busy){if(e==SpeechRecognizer.ERROR_INSUFFICIENT_PERMISSIONS||e==SpeechRecognizer.ERROR_CLIENT){status.setText("Voice recognition unavailable");active=false;}else handler.postDelayed(()->listen(),1000);}}
 public void onReadyForSpeech(Bundle b){} public void onBeginningOfSpeech(){} public void onRmsChanged(float f){} public void onBufferReceived(byte[] b){} public void onEndOfSpeech(){} public void onPartialResults(Bundle b){} public void onEvent(int i,Bundle b){}
 protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(r!=20||c!=RESULT_OK||d==null)return;String base=url.getText().toString();if(!base.startsWith("https://")){status.setText("Set HTTPS backend first");return;}new Thread(()->{try{android.net.Uri uri=d.getData();String name="resume.txt";try(android.database.Cursor cur=getContentResolver().query(uri,null,null,null,null)){if(cur!=null&&cur.moveToFirst()){int idx=cur.getColumnIndex(android.provider.OpenableColumns.DISPLAY_NAME);if(idx>=0)name=cur.getString(idx);}}byte[] bytes;try(java.io.InputStream in=getContentResolver().openInputStream(uri)){java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream();byte[] buf=new byte[8192];int n;while((n=in.read(buf))!=-1){out.write(buf,0,n);if(out.size()>5000000)throw new Exception();}bytes=out.toByteArray();}RequestBody body=new MultipartBody.Builder().setType(MultipartBody.FORM).addFormDataPart("file",name,RequestBody.create(bytes,MediaType.parse("application/octet-stream"))).build();try(Response resp=client.newCall(new Request.Builder().url(base.replaceAll("/+$","")+"/resume").post(body).build()).execute()){if(!resp.isSuccessful())throw new Exception();String s=new JSONObject(resp.body().string()).getString("text");runOnUiThread(()->resume.setText(s));}}catch(Exception e){runOnUiThread(()->status.setText("Resume upload failed"));}}).start();}
 protected void onStop(){super.onStop();stop();}protected void onDestroy(){if(speech!=null)speech.destroy();handler.removeCallbacksAndMessages(null);super.onDestroy();}
}
